macro_rules! Context {
    () => {
        # [doc = " Additional context to be passed to the credentials helper."] # [derive (Debug , Default , Clone , Eq , PartialEq)] pub struct Context { # [doc = " The protocol over which the credential will be used (e.g., https)."] pub protocol : Option < String > , # [doc = " The remote hostname for a network credential. This includes the port number if one was specified (e.g., \"example.com:8088\")."] pub host : Option < String > , # [doc = " The path with which the credential will be used. E.g., for accessing a remote https repository, this will be the repository’s path on the server."] # [doc = " It can also be a path on the file system."] pub path : Option < BString > , # [doc = " The credential’s username, if we already have one (e.g., from a URL, the configuration, the user, or from a previously run helper)."] pub username : Option < String > , # [doc = " The credential’s password, if we are asking it to be stored."] pub password : Option < String > , # [doc = " An OAuth refresh token that may accompany a password. It is to be treated confidentially, just like the password."] pub oauth_refresh_token : Option < String > , # [doc = " The expiry date of OAuth tokens as seconds from Unix epoch."] pub password_expiry_utc : Option < gix_date :: SecondsSinceUnixEpoch > , # [doc = " When this special attribute is read by git credential, the value is parsed as a URL and treated as if its constituent"] # [doc = " parts were read (e.g., url=<https://example.com> would behave as if"] # [doc = " protocol=https and host=example.com had been provided). This can help callers avoid parsing URLs themselves."] pub url : Option < BString > , # [doc = " If true, the caller should stop asking for credentials immediately without calling more credential helpers in the chain."] pub quit : Option < bool > , }
    };
}

Context!();